fields.InputDefinition:
{
  "goal": "Switch to the Knowledge Hub app (application switcher dropdown next to the logo) and click 'Vectors' in the left nav (fa-cubes icon). Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) vectors-management — confirm the Vector Management screen renders KPI cards, an 'Entity Sync Status' table (Entity / Document / Vectors / Last Synced / Status / Actions), and a sidebar with Vector DB Health + Embedding Model info (or a clear 'No entity documents configured for vectorization' empty state); use the view-toggle in the header to switch view modes and confirm the view responds, and if a sync row exists click its 'Sync' (play) button and confirm it enters a syncing/disabled state (you do NOT need it to finish); (2) suggest-document-dialog — click the 'Suggest Document' button in the Entity Sync Status panel header and confirm an 'AI Document Suggestion' slide-in panel opens with an entity picker (searchable dropdown) and a use-case selector (Duplicate Detection / Search / Classification) plus a 'Generate Template' button; pick an entity and a use case (you may click Generate to confirm a 'Generating with AI…' state, but you do NOT need to wait for or save the result), then confirm the panel can be closed. Keep going until both sections are done. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "vectors-management",
      "instruction": "Vector Management sync table + view-mode toggle",
      "visualCriteria": [
        "The Vectors screen shows KPI cards, an 'Entity Sync Status' table (Entity / Document / Vectors / Last Synced / Status / Actions), and a health/model sidebar (or a valid empty state); toggling the view mode changes the view, and if a row exists clicking Sync enters a syncing/disabled state"
      ]
    },
    {
      "name": "suggest-document-dialog",
      "instruction": "AI Suggest Document dialog",
      "visualCriteria": [
        "Clicking 'Suggest Document' opens an AI Document Suggestion panel with an entity picker and use-case options (Duplicate Detection / Search / Classification); selecting an entity/use-case and optionally clicking Generate produces a generating state or a suggested result, and the panel can be closed"
      ]
    }
  ]
}
